<?php include "../auth/cek_login.php"; include "../koneksi.php"; $q=mysqli_query($conn,"SELECT b.*,k.nama_kategori FROM barang b JOIN kategori k ON b.id_kategori=k.id ORDER BY b.id DESC"); ?><!doctype html><html><head><title>Barang</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Data Barang</h1><a class="btn" href="tambah.php">+ Tambah Barang</a><a class="btn" href="../dashboard.php">Dashboard</a><table><tr><th>No</th><th>Kode</th><th>Nama</th><th>Kategori</th><th>Harga/Hari</th><th>Stok</th><th>Kondisi</th><th>Aksi</th></tr><?php $n=1;while($d=mysqli_fetch_assoc($q)): ?><tr><td><?=$n++?></td><td><?=$d['kode_barang']?></td><td><?=$d['nama_barang']?></td><td><?=$d['nama_kategori']?></td><td>Rp <?=number_format($d['harga_sewa'],0,',','.')?></td><td><?=$d['stok']?></td><td><?=$d['kondisi']?></td><td><a href="edit.php?id=<?=$d['id']?>">Edit</a> | <a href="hapus.php?id=<?=$d['id']?>" onclick="return confirm('Hapus?')">Hapus</a></td></tr><?php endwhile; ?></table></div></body></html>